using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.IO;
using ConRoi.Investigation.V36;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (!EditorApplication.isPlaying)
            {
                r.Log("Edit mode scene=" + EditorSceneManager.GetActiveScene().path + " dirty=" + EditorSceneManager.GetActiveScene().isDirty);
                return;
            }

            var s = Object.FindFirstObjectByType<InvestigationSession>();
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r102/profile-tests");
            var type = System.Type.GetType("UnityEditor.GameView,UnityEditor");
            var w = EditorWindow.GetWindow(type);
            w.ShowUtility();
            w.position = new Rect(0, 0, 1280, 850);
            w.Focus();
            File.WriteAllText("Test/KetQua/investigation_r102/live-state.txt", "player=" + s.movement.transform.position + " page=" + s.Page + " save=" + s.SavePath + " oldjourney=" + (Object.FindFirstObjectByType<DieuPhoiHanhTrinh>() != null));
            ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r102/game-first.png");
            r.Log("Game window ready, private investigation profile; screenshot scheduled");
        }
    }
}

